body=[p('Contoh pembelajaran sintetis. Seluruh angka merupakan asumsi perancangan dan proyeksi, bukan hasil penjualan, riset pelanggan, kemitraan, atau pendanaan yang telah diperoleh.'),h('Ringkasan Eksekutif','summary'),p('Ruang Rapi menyediakan paket penyimpanan terpasang untuk penghuni kos yang membutuhkan meja belajar dan ruang barang yang lebih tertata. Pelanggan memilih paket berdasarkan ukuran ruang dan barang yang dipakai sehari-hari. Harga Rp450.000 mencakup komponen standar, pemasangan, serta pemeriksaan hasil, sehingga pembeli menilai biaya ruang yang siap digunakan sejak awal.'),p('Perusahaan memperoleh pendapatan dari setiap paket yang selesai dipasang dan diterima pelanggan. Mitra perakitan menyiapkan komponen sesuai ukuran pesanan; pemasang menangani penataan di lokasi. Koordinasi, pemeriksaan mutu, dan layanan pelanggan tetap dipegang Ruang Rapi. Pembelian berikutnya berasal dari area lain yang ingin ditata, dengan modul yang tetap kompatibel.'),p(f'Proyeksi tahun pertama mencakup {s["orders"]} pesanan dengan pendapatan Rp{fmt(s["revenue"])} juta dan surplus operasi sebelum penyusutan Rp{fmt(s["ebitda"])} juta. Kebutuhan pendanaan termasuk cadangan kas Rp{fmt(s["funding_need_including_floor"])} juta ditutup melalui usulan modal Rp30 juta. Penjualan tumbuh bersama slot pemasangan, sementara arus kas mempertimbangkan penerimaan tagihan pada bulan berikutnya.'),h('Pelanggan Penawaran dan Pilihan','offer'),p('Pasar awal dipusatkan pada penghuni kos dalam radius layanan tiga kilometer. Batas ini menjaga waktu perjalanan dan memudahkan demonstrasi di ruang yang benar-benar akan digunakan. Calon pelanggan mengirim ukuran meja serta foto barang melalui WhatsApp, lalu menerima pilihan susunan dan jadwal sebelum menyetujui pesanan. Pengelola kos berperan sebagai jalur pengenalan dan koordinator pesanan kelompok; peran ini merupakan desain kerja sama yang akan ditawarkan.'),p('Pelanggan yang memiliki waktu dan alat sendiri dapat memilih penataan mandiri dengan biaya jasa lebih rendah. Toko furnitur menjadi alternatif untuk kebutuhan lemari berkapasitas besar. Ruang Rapi dipilih ketika pelanggan menghargai penyesuaian ukuran, pemasangan, dan satu pihak yang bertanggung jawab atas hasil. Penawaran membatasi perubahan ukuran pada komponen standar agar kenyamanan tersebut tetap dapat dibayar oleh harga paket.'),h('Akuisisi dan Pembelian Lanjutan','market'),p('Demonstrasi sebelum–sesudah mengarahkan calon pembeli ke konsultasi ukuran. Anggaran pemasaran Rp1 juta per bulan membiayai materi demonstrasi dan jangkauan lokal. Model memakai 40 calon pembeli yang sudah memenuhi kriteria pada bulan pertama dan 90 pada bulan kedua belas, dengan konversi asumsi 50%; angka ini berlaku untuk konsultasi berkualifikasi, bukan seluruh penonton konten. Permintaan pembelian lanjutan dihitung sebesar 20% pesanan bulan sebelumnya dan dibulatkan ke bawah. Seluruh penggerak dan batas kapasitas dapat ditelusuri pada Lampiran A.1.'),h('Operasi dan Pengendalian Mutu','operations'),p('Sesudah penawaran disetujui, koordinator mengunci ukuran, komponen, dan slot pemasangan. Mitra perakitan memotong serta menyiapkan bagian; pemasang memeriksa kelengkapan sebelum berangkat, memasang di lokasi, lalu menunjukkan penggunaan kepada pelanggan. Serah terima memeriksa kestabilan, kesesuaian ukuran, dan akses barang. Komponen yang gagal diperbaiki sebelum pesanan dinyatakan selesai.'),p('Satu pesanan memakai 2,5 jam kerja pemasang dengan biaya jasa Rp50.000. Kapasitas tumbuh dari 24 menjadi 48 pesanan per bulan, setara maksimum 120 jam pemasangan yang dapat dijadwalkan. Koordinasi pendiri dibayar melalui biaya tetap. Perubahan ukuran di luar paket menerima penawaran terpisah; keterlambatan komponen memicu penjadwalan ulang sebelum pelanggan membayar pekerjaan yang belum dapat dipenuhi.'),h('Ekonomi Pendanaan dan Kas','finance'),p('Biaya langsung Rp250.000 per paket terdiri atas komponen Rp180.000, jasa pemasangan Rp50.000, serta perjalanan dan bahan habis pakai Rp20.000. Kontribusi Rp200.000 membayar biaya tetap Rp4 juta dan pemasaran Rp1 juta per bulan. Dengan konfigurasi ini, 25 pesanan menutup biaya operasi sebelum penyusutan. Rincian biaya, sensitivitas, dan hubungan kas tersedia pada Lampiran A.2.'),t('Tabel 1 Proyeksi tahun pertama',['Ukuran','Rp juta'],[['Pendapatan',fmt(s['revenue'])],['Biaya langsung',fmt(s['direct_cost'])],['Biaya tetap dan pemasaran',fmt(s['fixed_cost']+s['marketing'])],['Surplus operasi sebelum penyusutan',fmt(s['ebitda'])],['Laba operasi setelah penyusutan',fmt(s['operating_profit'])],['Penerimaan kas',fmt(s['receipts'])],['Piutang akhir tahun',fmt(s['closing_receivables'])],['Kas akhir setelah modal Rp30 juta',fmt(s['closing_funded_cash'])]],[11,5]),p('Laba operasi tersebut belum dikurangi pengeluaran persiapan Rp2 juta pada awal proyek, pajak, bunga, atau distribusi pemilik. Peralatan Rp6 juta dibayar di awal dan disusutkan selama 36 bulan. Untuk pesanan kelompok, koordinator mengumpulkan pembayaran dan menyelesaikan tagihan perusahaan pada bulan berikutnya. Model menerapkan jeda ini untuk seluruh penjualan; piutang akhir Rp21,60 juta menjelaskan mengapa kas berbeda dari laba.'),p('Kas proyek sebelum pendanaan berakhir minus Rp1,40 juta, sehingga investasi belum kembali dalam horizon dua belas bulan. NPV dua belas bulan pada diskonto tahunan 12% sebesar minus Rp2,94 juta, tanpa menambahkan penerimaan piutang setelah akhir horizon atau nilai terminal. Usulan modal Rp30 juta menjaga cadangan Rp3 juta; saldo terendah setelah modal Rp8,95 juta muncul pada bulan ketiga. Modal ini belum dinyatakan tersedia.'),h('Pertumbuhan dan Kesimpulan','growth'),p('Pada akhir tahun, permintaan melampaui kapasitas dan delapan pesanan dalam setahun belum dapat dilayani. Penambahan pemasang diarahkan pada pesanan yang mampu membayar biaya kerja berikutnya, dengan pemeriksaan kontribusi, waktu serah terima, dan penyelesaian tagihan sebelum kapasitas dibuka. Koordinator menahan pesanan kelompok baru ketika tagihan melewati batas pembayaran yang disepakati.'),p('Ruang Rapi menghubungkan kebutuhan ruang kecil dengan paket yang jelas, pekerjaan yang dibayar, dan hasil yang dapat diperiksa. Pertumbuhan berlangsung melalui pengulangan susunan komponen, slot kerja, serta layanan pelanggan yang sama. Kekuatan bisnisnya terletak pada kenyamanan ruang siap pakai; keberlanjutan pertumbuhannya bergantung pada disiplin kapasitas dan penerimaan kas yang sudah terlihat dalam perhitungan.')]
monthly=t('Tabel A1 Jadwal pesanan dan keuangan',['Bln','Pes.','Omzet\nRp juta','Surplus operasi\nRp juta','Kas proyek\nRp juta','Kas dengan modal\nRp juta','Piutang\nRp juta'],[[r['month'],r['orders'],fmt(r['revenue']),fmt(r['ebitda']),fmt(r['project_cash']),fmt(r['funded_cash']),fmt(r['receivables'])] for r in rows],[1.1,1.5,2.3,2.6,2.8,3,2.7])
apps=[{'id':'A.1','title':'Penggerak dan Jadwal Bulanan','return_to':'market','blocks':[p('Sumber perhitungan: asumsi sintetis dalam finance-input.json dan hasil model/finance.json. Calon pembeli, konversi, pembelian lanjutan, kapasitas, harga, dan biaya merupakan masukan perancangan. Permintaan yang tidak tertampung tidak dihitung sebagai penjualan dan tidak dibawa otomatis ke bulan berikutnya.'),monthly,p('Biaya tetap per bulan: koordinasi pendiri Rp2,5 juta, ruang kerja Rp1 juta, dan administrasi/sistem Rp0,5 juta. Biaya pemasaran terpisah Rp1 juta. Penjualan, penerimaan kas, dan saldo piutang menggunakan periode yang sama; nilai dibulatkan hanya untuk tampilan.'),{'type':'page_break'}]},{'id':'A.2','title':'Biaya Sensitivitas dan Arus Kas','return_to':'finance','blocks':[{'type':'image','path':'assets/charts/cash.png','width_cm':16,'caption':'Gambar A1 Kas proyek dan kas setelah usulan pendanaan dalam juta rupiah'},p('Kurva dihitung dari jadwal bulanan yang sama. Selisih kedua kurva adalah modal Rp30 juta, bukan tambahan pendapatan atau laba. Saldo proyek mencakup peralatan dan persiapan di awal, serta biaya operasi saat ini dengan penerimaan penjualan satu bulan kemudian.'),t('Tabel A2 Sensitivitas satu penggerak',['Skenario','Surplus operasi\nRp juta','Kebutuhan modal\nRp juta'],[['Dasar',fmt(s['ebitda']),fmt(s['funding_need_including_floor'])]]+[[label,fmt(case['ebitda']),fmt(case['funding_need_including_floor'])] for label,case in [('Harga turun 10%',f['sensitivity'][0]),('Calon pembeli turun 20%',f['sensitivity'][2]),('Biaya langsung naik 10%',f['sensitivity'][4])]],[8,4,4]),p('Setiap sensitivitas mengubah satu masukan dan menghitung ulang pesanan, kapasitas, biaya, piutang, serta kas melalui model yang sama. Perubahan harga tidak sekaligus mengubah minat pasar dalam perhitungan ini; tabel menunjukkan pengaruh harga pada ekonomi paket dengan masukan permintaan yang tetap. Tidak ada probabilitas keberhasilan yang diklaim.')]}]
